<?php
/**
 * Plugin Name: پاک‌سازی داده‌های آزمایشی دانشگران
 * Version: 1.0.1
 * Description: ابزار موقت مدیر کل؛ پیش‌نمایش و حذف داده‌های آزمایشی با حفظ سایت و حساب اجراکننده.
 */
if(!defined('ABSPATH'))exit;
function dgtr_allowed(){return !is_multisite()&&current_user_can('manage_options')&&in_array('administrator',(array)wp_get_current_user()->roles,true);}
function dgtr_tables(){global $wpdb;$names=explode(' ','dgs_att_records dgs_att_sessions dgs_hw_submissions dgs_homework dgs_quiz_attempts dgs_quiz_questions dgs_quizzes dgs_mark_requests dgs_mark_audit dgs_mark_entries dgs_mark_states dgs_mark_deadlines dgs_report_feedback dgs_grades dgs_study_feedback dgs_study_entries dgs_study_days dgs_timetables dgs_fin_payments dgs_fin_installments dgs_fin_accounts dgs_sms_items dgs_sms_batches dgs_counseling dgs_teaching dgs_enrollments dgs_subjects dgs_classes');$out=array();foreach($names as $name){$t=$wpdb->prefix.$name;if($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$wpdb->esc_like($t)))===$t)$out[]=$t;}return $out;}
function dgtr_plan(){global $wpdb;$keeper=get_current_user_id();$users=get_users(array('exclude'=>array($keeper),'fields'=>array('ID','user_login','display_name'),'orderby'=>'ID','order'=>'ASC'));$posts=$wpdb->get_col("SELECT ID FROM {$wpdb->posts} WHERE post_type IN ('dgs_teacher','dgs_class','dgs_star','dgs_request') ORDER BY ID");$tables=array();foreach(dgtr_tables() as $t){$n=$wpdb->get_var("SELECT COUNT(*) FROM `$t`");if($n===null)throw new RuntimeException('خواندن جدول ممکن نشد.');$tables[$t]=(int)$n;}return array('keeper'=>$keeper,'users'=>$users,'posts'=>array_map('intval',$posts),'tables'=>$tables);}
function dgtr_hash($plan){return hash('sha256',wp_json_encode($plan));}
add_action('admin_menu',function(){if(dgtr_allowed())add_management_page('پاک‌سازی آزمایشی','پاک‌سازی آزمایشی دانشگران','manage_options','dg-test-reset','dgtr_page');});
function dgtr_page(){if(!dgtr_allowed())wp_die('دسترسی ندارید.');echo '<div class="wrap" dir="rtl"><h1>پاک‌سازی داده‌های آزمایشی دانشگران</h1>';if(get_option('dgtr_completed')){echo '<div class="notice notice-success"><p>پاک‌سازی انجام شده است. این افزونه را غیرفعال و حذف کنید؛ اطلاعات واقعی جدید را با این ابزار پاک نکنید.</p></div></div>';return;}try{$p=dgtr_plan();}catch(Throwable $e){wp_die(esc_html($e->getMessage()));}$u=wp_get_current_user();echo '<p><strong>حسابی که حفظ می‌شود: '.esc_html($u->user_login).' — '.esc_html($u->display_name).'</strong></p><p>تمام کاربران دیگر (حتی مدیر کل دیگر)، کلاس‌ها، دروس و سوابق آموزشی همه سال‌ها حذف می‌شوند. معرفی اعضای کادر، کلاس‌های کنکور - تقویتی، دانش‌آموزان برگزیده و درخواست‌های آزمایشی نیز حذف می‌شوند.</p><p>صفحات، نوشته‌ها، قالب‌های المنتور، رسانه‌ها، لوگوها، تنظیمات مدرسه و اتصال پیامک حفظ می‌شوند. محتوای عمومی متعلق به کاربران حذف‌شونده به حساب شما منتقل می‌شود. این ابزار فایل بکاپ را بررسی یا ایجاد نمی‌کند.</p><h2>پیش‌نمایش حذف</h2><p>کاربران: '.count($p['users']).' — محتوای آموزشی/درخواست‌ها: '.count($p['posts']).'</p><details><summary>نام حساب‌های حذف‌شونده</summary><ul>';foreach($p['users'] as $row)echo '<li>'.esc_html($row->user_login.' — '.$row->display_name).'</li>';echo '</ul></details><table class="widefat"><thead><tr><th>جدول سوابق</th><th>تعداد</th></tr></thead><tbody>';foreach($p['tables'] as $t=>$count)echo '<tr><td>'.esc_html($t).'</td><td>'.$count.'</td></tr>';echo '</tbody></table><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('dgtr_execute');echo '<input type="hidden" name="action" value="dgtr_execute"><input type="hidden" name="plan_hash" value="'.esc_attr(dgtr_hash($p)).'"><p><label><input type="checkbox" name="backup" value="1" required> بکاپ کامل را روی کامپیوتر دانلود کرده‌ام و فهرست بالا را بررسی کردم.</label></p><p><label>برای تأیید، عبارت «حذف آزمایشی» را وارد کنید: <input name="confirm" required autocomplete="off"></label></p><p><label>رمز فعلی همین حساب مدیر کل: <input type="password" name="password" required autocomplete="current-password"></label></p><p><button class="button button-primary">حذف دائمی داده‌های آزمایشی</button></p></form></div>';}
function dgtr_execute($plan){global $wpdb;if(!dgtr_allowed()||(int)$plan['keeper']!==get_current_user_id())throw new RuntimeException('حساب مجاز نیست.');if(get_option('dgtr_completed'))throw new RuntimeException('این ابزار قبلاً اجرا شده است.');if(!add_option('dgtr_running',time(),'','no'))throw new RuntimeException('پاک‌سازی دیگری در حال اجراست؛ صفحه را نبندید.');$sms=false;try{if(!add_option('dgs_sms_worker','reset|'.time(),'','no'))throw new RuntimeException('پردازش پیامک در حال اجراست؛ چند دقیقه بعد دوباره تلاش کنید.');$sms=true;
// Use DELETE rather than DROP/TRUNCATE: schemas and ID sequences stay intact.
foreach($plan['tables'] as $table=>$count){if(!in_array($table,dgtr_tables(),true))throw new RuntimeException('جدول خارج از محدوده است.');if($wpdb->query("DELETE FROM `$table`")===false)throw new RuntimeException('پاک‌سازی جدول کامل نشد: '.$table);}
require_once ABSPATH.'wp-admin/includes/user.php';foreach($plan['posts'] as $id){$post=get_post($id);if($post&&!in_array($post->post_type,array('dgs_teacher','dgs_class','dgs_star','dgs_request'),true))throw new RuntimeException('محتوای خارج از محدوده.');if($post&&!wp_delete_post($id,true))throw new RuntimeException('حذف محتوای آزمایشی کامل نشد.');}
foreach($plan['users'] as $row){$id=(int)$row->ID;if($id===(int)$plan['keeper'])throw new RuntimeException('حساب اصلی محافظت شده است.');WP_Session_Tokens::get_instance($id)->destroy_all();if(get_userdata($id)&&!wp_delete_user($id,(int)$plan['keeper']))throw new RuntimeException('حذف کاربر کامل نشد.');}
delete_option('dgs_edu_audit');delete_option('dgs_sms_auto_warning');delete_option('dgs_mg_started_period');if(function_exists('dgs_catalog_invalidate'))dgs_catalog_invalidate(0);$remaining=dgtr_plan();if(count($remaining['users'])||count($remaining['posts'])||array_sum($remaining['tables']))throw new RuntimeException('برخی داده‌ها باقی مانده‌اند؛ دوباره پیش‌نمایش را بررسی کنید.');update_option('dgtr_completed',array('keeper'=>$plan['keeper'],'at'=>current_time('mysql')),false);
}finally{if($sms)delete_option('dgs_sms_worker');delete_option('dgtr_running');}}
add_action('admin_post_dgtr_execute',function(){if(!dgtr_allowed()||($_SERVER['REQUEST_METHOD']??'')!=='POST')wp_die('دسترسی ندارید.','',array('response'=>403));check_admin_referer('dgtr_execute');$d=wp_unslash($_POST);if(($d['backup']??'')!=='1')wp_die('تیک تأیید دانلود بکاپ را بزنید. هیچ حذفی انجام نشده است.');$confirm=is_string($d['confirm']??null)?preg_replace('/[\s\x{200c}\x{200d}]+/u','',strtr($d['confirm'],array('ي'=>'ی','ك'=>'ک'))):'';if($confirm!=='حذفآزمایشی')wp_die('عبارت تأیید باید «حذف آزمایشی» باشد. هیچ حذفی انجام نشده است.');$fresh=get_userdata(get_current_user_id());if(!$fresh||!is_string($d['password']??null)||!wp_check_password($d['password'],$fresh->user_pass,$fresh->ID))wp_die('رمز فعلی حساب مدیر کل وردپرس تأیید نشد. رمز ورود همین حساب را وارد کنید، نه رمز هاست. هیچ حذفی انجام نشده است.');try{$plan=dgtr_plan();if(!is_string($d['plan_hash']??null)||!hash_equals(dgtr_hash($plan),$d['plan_hash']))throw new RuntimeException('اطلاعات از زمان پیش‌نمایش تغییر کرده است؛ صفحه پیش‌نمایش را دوباره باز کنید.');dgtr_execute($plan);}catch(Throwable $e){wp_die(esc_html($e->getMessage()).' ممکن است بخشی از پاک‌سازی انجام شده باشد. پیش‌نمایش را بررسی کنید؛ حساب و صفحات عمومی حفظ شده‌اند.');}wp_safe_redirect(admin_url('tools.php?page=dg-test-reset'));exit;});
// Block new web writes while cleanup is running. Public GETs and the cleanup request remain available.
add_action('init',function(){if(get_option('dgtr_running')&&($_SERVER['REQUEST_METHOD']??'GET')!=='GET'&&($_POST['action']??'')!=='dgtr_execute')wp_die('پاک‌سازی آزمایشی در حال انجام است. کمی بعد تلاش کنید.','',array('response'=>503));},-999);
